  "gorsel": "<table class=\"tablo\"><tr><th>Harf</th><th>Araç</th></tr><tr><td>K</td><td>Cımbız</td></tr><tr><td>L</td><td>El arabası</td></tr><tr><td>M</td><td>Maşa</td></tr><tr><td>N</td><td>Pense</td></tr></table>",
